Canary（金丝雀）按 Shadow → 5% → 25% → 50% → 100% 逐步放量，每个阶段评估错误率、质量、延迟、安全；任一不达标就回滚到 ROLLED_BACK，而不是继续放量。

```python
class CanaryController:
    def __init__(self, evaluator, min_observation_minutes=30):
        self.evaluator = evaluator
        self.min_observation = min_observation_minutes
        self.current_phase = DeployPhase.SHADOW
    def advance_phase(self):
        phases = list(DeployPhase)
        idx = phases.index(self.current_phase)
        result = self._evaluate_current_phase()
        if result["pass"]:
            self.current_phase = phases[idx + 1]
            return {"status": "advanced", "to": self.current_phase.value}
        self.current_phase = DeployPhase.ROLLED_BACK
        return {"status": "rolled_back", "reason": result["reason"]}
    def _evaluate_current_phase(self):
        m = self.evaluator.get_current_metrics()
        checks = {
            "error_rate_ok": m.get("error_rate", 1.0) < 0.01,
            "quality_ok": m.get("quality_score", 0) > 0.8,
            "no_safety_issues": m.get("safety_violations", 1) == 0,
        }
        failed = [k for k, v in checks.items() if not v]
        return {"pass": all(checks.values()), "reason": ",".join(failed)}
```

输入护栏把多个检查串起来跑，命中 BLOCK / REWRITE 就立即返回。注入检测用一组正则匹配「忽略以上指令」「你现在是…」这类经典攻击话术（生产里还会叠加 LLM 分类器）。

```python
class InputGuardrail:
    def check(self, user_input):
        checks = [self._check_prompt_injection, self._check_length, self._check_topic_boundary]
        for check_fn in checks:
            result = check_fn(user_input)
            if result.verdict in (GuardrailVerdict.BLOCK, GuardrailVerdict.REWRITE):
                return result
        return GuardrailResult(GuardrailVerdict.PASS, "所有检查通过", user_input)
    def _check_prompt_injection(self, text):
        patterns = [
            r"ignore\s+(previous|above|all)\s+instructions",
            r"you\s+are\s+now\s+(?:a|an)\s+",
            r"forget\s+(everything|what)",
            r"new\s+instructions?\s*:",
        ]
        for pattern in patterns:
            if re.search(pattern, text, re.IGNORECASE):
                return GuardrailResult(GuardrailVerdict.BLOCK, f"检测到注入: {pattern}", text)
        return GuardrailResult(GuardrailVerdict.PASS, "", text)
```

Agent RBAC 把链路从「用户→角色→权限」延伸成「用户→agent→工具→权限」。给每个 agent 绑角色，角色声明它能碰哪些资源、用哪些工具、单会话最多几步、哪些操作需要人工审批。

```python
class AgentRBAC:
    def __init__(self):
        self.roles = {}
        self.agent_assignments = {}
    def define_role(self, role_name, permissions):
        self.roles[role_name] = permissions
    def assign_role(self, agent_id, role_name):
        if role_name not in self.roles:
            raise ValueError(f"角色 {role_name} 不存在")
        self.agent_assignments[agent_id] = role_name
    def check_permission(self, agent_id, action, resource):
        role_name = self.agent_assignments.get(agent_id)
        if not role_name:
            return False
        role = self.roles.get(role_name, {})
        resource_perms = role.get("permissions", {}).get(resource, [])
        return action in resource_perms
```

模型漂移最隐蔽——你 git log 干干净净，提供商却把模型从一个版本换到了下一个。检测办法是部署时用一组固定探针请求采基线，之后定期重跑、和基线比长度漂移和属性是否还满足（比如该包含的关键词还在不在）。

```python
class ModelDriftDetector:
    def __init__(self, probe_suite, llm_client):
        self.probes = probe_suite
        self.llm = llm_client
        self.baseline = {}
    def capture_baseline(self, runs=5):
        for probe in self.probes:
            responses = [self.llm.generate([{"role": "user", "content": probe["input"]}]) for _ in range(runs)]
            self.baseline[probe["id"]] = {"avg_length": sum(len(r) for r in responses) / len(responses)}
        return self.baseline
    def check_drift(self, runs=5):
        drifts = []
        for probe in self.probes:
            base = self.baseline.get(probe["id"])
            current = [self.llm.generate([{"role": "user", "content": probe["input"]}]) for _ in range(runs)]
            cur_len = sum(len(r) for r in current) / len(current)
            length_drift = abs(cur_len - base["avg_length"]) / max(base["avg_length"], 1)
            if length_drift > 0.3:
                drifts.append({"probe_id": probe["id"], "length_drift": length_drift})
        return {"drifted_probes": len(drifts), "verdict": "DRIFT_DETECTED" if drifts else "STABLE"}
```
